({ context }) => {
    const args = context.args || "";
    if (!args.trim())
      throw Error("\u041A\u043E\u043C\u0430\u043D\u0434\u0430 \u043D\u0435 \u0443\u043A\u0430\u0437\u0430\u043D\u0430");
    const result = {};
    if (args.includes("-a") || args.includes("--all"))
      result.all = true;
    if (args.includes("--amend"))
      result.amend = true;
    if (args.includes("-s") || args.includes("--signoff"))
      result.signoff = true;
    if (args.includes("-n") || args.includes("--no-verify"))
      result.noVerify = true;
    if (args.includes("--dry-run"))
      result.dryRun = true;
    if (args.includes("-v") || args.includes("--verbose"))
      result.verbose = true;
    if (args.includes("-e") || args.includes("--edit"))
      result.edit = true;
    const msgMatch = args.match(/-m\s+"([^"]+)"/) || args.match(/-m\s+'([^']+)'/) || args.match(/-m\s+(\S+)/);
    if (msgMatch && msgMatch[1])
      result.message = msgMatch[1];
    return result;
  }

async ({ context }) => {
    const cmd = `git commit -m ${JSON.stringify(context.message)}`, result = await Bun.$`${cmd}`.quiet().text();
    if (!result.includes("created") && !result.includes("mode"))
      throw Error(result || "\u041D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u0441\u043E\u0437\u0434\u0430\u0442\u044C \u043A\u043E\u043C\u043C\u0438\u0442");
  }

